import os, re, subprocess
SP = os.path.dirname(os.path.abspath(__file__))
def rd(n): return open(f'{SP}/{n}', encoding='utf-8', errors='ignore').read()
MX = re.search(r'MATRIX: (\d+)/(\d+)', rd('ch14_runner_run1.out')).groups(); CC = re.search(r'checkpoint_check: (\d+) rows, (\d+) miss, (\d+) raised', rd('ch14_checkpoint_check.out')).groups()
STORY = rd('ch14b_chain_story.txt').strip(); TAPE = rd('ch14b_tape_story.txt').strip()
sw = rd('gates_ch14b/sweep.out'); SW = (len(re.findall(r'^PASS +cold_run_\w+\.py', sw, re.M)), sum(int(a) for a, b in re.findall(r'score=(\d+)/(\d+)', sw)))
RG = re.search(r'DECLARED (\d+); DEBT (\d+); FAILS (\d+)', rd('gates_ch14b/register.out')).groups(); DG = re.search(r'(\d+) daemons', rd('gates_ch14b/daemon.out')).group(1); DP = re.search(r'(\d+) edges', rd('gates_ch14b/dependency.out')).group(1)
rows = [l.split('\t') for l in rd('ch14b_timing.tsv').split('\n') if l.strip()]; T = [(r[1], int(r[2])) for r in rows if len(r) >= 3 and r[1].startswith('12b')]; TSUM = sum(s for _, s in T)
p = f'{SP}/commit_msg_ch14b.txt'; m = open(p, encoding='utf-8').read()
PH = '(THE HEADLINE WRITTEN AT RUN B)'; assert m.count(PH) == 1, m.count(PH)
HEAD = ("THE FOOD LAWS AND THE TITHES COMPILED AS FIVE LAWS AT THE CHAPTER'S OWN DAY OVER THE TWIN CHAPTER'S CELLS BY CALL (SHEMINI'S CLASSIFIER ANSWERING THE BEASTS, THE WATER AND THE BIRDS; THE FOUR ITS OWN EXCEPTION ROWS), THE CUTTING'S BAR AT ITS FIRST SEAT WITH 'NO FACTIONS' FROM THE SAME WORD, THE CARCASS'S BAN AT THE SEAT THE SANCTIONS ENGINE ITSELF NAMES, THE SECOND TITHE NAMED BY THE SHELF WITH THE EXILE'S ARM, THE THIRD YEAR'S TITHE WITH ITS REMOVAL DATE A CLOCK DATUM ON THE CALENDAR'S OWN KEY AND THE COUNT BY CALL TO THE CYCLE; THE BIRDS' SIGNS A PARAMETER IN THREE LAYERS — THE CODE/DATA SEPARATION LAW'S OWN CASE; THE CLASS FROM THE FOUR NAMED BY GENERAL-PARTICULAR-GENERAL, THE CHAPTER'S OWN VERSE THE SOURCE OF THE METHOD (NAZIR 35b:3); TWO REUSES, TWO COUNT SEATS RETYPED BY THE GREP; FIVE OWN-DAY LINES, NO MARKER; AND THE SCENE OF SEVENTY-ONE PERSONS MATCHING ITS PREDICTION ON THE FIRST PASS. On the owner's words \"Go\" (RUN A), \"Reread\" and \"Go\" (the docket D1), \"Go\" (D2), \"Reread and go\" (RUN B and the tail), 2026-09-21/22; World/step9/DEUTERONOMY_WALK.md \"Sitting 12b — THE COMPILE OF CHAPTER 14 … THE DESIGN\", its two \"THE DOCKET — AS RUN\" paragraphs and \"Sitting 12b — THE COMPILE OF CHAPTER 14 — AS BUILT\" — THE TWO-RUN RULE's seventh compile sitting under THE COST RULES with the docket clause applied twice: five clean compaction points (the state doc's #205 and its addenda 1-4)")
m = m.replace(PH, HEAD)
PARA = (" RUN B (2026-09-22, on the owner's \"Reread and go\" after the compaction at #205 addendum 2): readback_probes.py Q37-Q39 written to FAIL before the runner (35/39 — Q32's two reuse counts and the blocks retyped with them: THE GREP DECIDED TWO COUNT SEATS, DD2 in the sequence file retyped at the literals step); the types (event_vocabulary 1155 -> 1161, effect_vocabulary 1056 -> 1061 with the two reused rows AMENDED, law_food_tithe the 74th daemon with eight WRAPPED, the span and eighteen CALL edges, I5 74, the five parameters — the_birds_signs in three layers, the_carcass_table with the precedence, the_moneys_form with the possession clause, the_removal_date, the_tithes_new_year with the first third; the register file untouched, DECLARED 98); the callees' facts printed before any assert (eighteen runners — the classifier's water keys read at the source after the print's guessed dict, moadim without a cell for 23:22 called through its daemon's branch, temurah's tithe a string case, yovel's cycle a year); THE RUNNER cold_run_food_tithe.py the 69th (the helpers by content markers, the ink block from the reading's instrument in three blocks with 47 asserts, the parser's facts typed from the ink's own asserts; seven cells and the table, 78 asks; twenty-nine readback rows — VERBATIM 6 / VARIANT 11 / EXPANDED 4 / SUPPLIED 8, four with their writes, 14:21 EXPANDED with its write, no pointer row; 56 DATA rows; seventy-one persons — the seven write asks case rows, not persons; the fast checker four passes, the scene and the narrative matching their predictions on the first): %s/%s ON ITS FIRST GRADED RUN; the recorder with the cache off, the stitcher with no marker (PLACEMENT page_order 1159 -> 1164, CENSUS on the tape 1327 -> 1332, kinds 872 -> 877), the literals (RUN (1332, 96, 88, 0, 12, 1641, 45, 319, the four pairs, 127), PREVIOUS_RUN 11b's exactly, DF1-DF9, DD2 retyped); %s; checkpoint_check.py --all (%s rows, %s miss — the eighteen known, %s raised); the records writer and the copier written; THE GATES CHAIN LAUNCHED at the run's end. THE TAIL (the same window, the chain's summary read once when the harness notified): %s — the daemon gate %s daemons, the dependency gate %s edges, the register gate DECLARED %s / DEBT %s / FAILS %s, the sweep %s/%s at %s graded cells, the home-path gate; THE RECORDS from the sheet in one call (write_ch14b_records.py — the map's AS BUILT with the timing table and eight lessons, COMPILE_DEBT's sitting-12 box PAID and the 12b box, MIDDOT's compile entry with every code checked, RESEARCH_LOG, THE_STEPS, THE_BRIEFING, THE_LOOP's step-6 row, RESUME, RECORD_FORMS, the state doc's #205 addenda 3-4, the addenda §60, the recovery page, the memory); the forms in World/step9/forms_deuteronomy_walk/. EVERY STEP TIMED — 12b's %d steps, %d machine seconds. THE LESSONS (eight, in the AS BUILT): a runner cannot import the sequence file; a classifier's keys are read at the source; a runner without a cell for a verse is called through its daemon's branch; an edge may name a verse in its taught_by; the DATA count read from the print; the scene's prediction from the design's arithmetic held; a write ask is a case row, not a person; THE TWO-RUN RULE HELD on its seventh compile sitting."
        % (MX[0], MX[1], TAPE, CC[0], CC[1], CC[2], STORY, DG, DP, RG[0], RG[1], RG[2], SW[0], SW[0], SW[1], len(T), TSUM))
if 'RUN B (2026-09-22' not in m: m = m.rstrip('\n') + PARA + '\n'
